const schema31 = {"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://d3cloud.io/floorspec/schema/core/0.1/floorspec.bundle.json","$ref":"#/$defs/floorspec","$defs":{"asset":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 8.6's table; the reference canonicalizer reads them as its table of constant defaults (9.2 step 1).","title":"Asset","description":"8.6: a file the document refers to — a texture image in this draft. An asset MUST have exactly one of `path` and `uri` (FS-CORE-8.6.1). It has only the members of its table (FS-CORE-1.4.1).","type":"object","required":["sha256","mediaType"],"properties":{"path":{"title":"Path","description":"8.6: where the file is, relative to the document. A path MUST be relative, use / as its separator, and contain no empty, . or .. segment (FS-CORE-8.6.2): so it does not start with /, contains no \\, has no colon in its first segment (which would make it a URI with a scheme or a drive-letter path), and has no // and no trailing /.","type":"string","pattern":"^(?:[^/\\\\.:]|[^/\\\\.:][^/\\\\:]|\\.[^/\\\\.:]|[^/\\\\:]{3,})(?:/(?:[^/\\\\.]|[^/\\\\.][^/\\\\]|\\.[^/\\\\.]|[^/\\\\]{3,}))*$"},"uri":{"title":"URI","description":"8.6: where the file is on the web, an absolute https: URI (RFC 3986) with an authority: only the characters RFC 3986 allows, with every % starting a percent-encoding.","type":"string","format":"uri","pattern":"^https://(?:[A-Za-z0-9._~:/?#\\[\\]@!$&'()*+,;=-]|%[0-9A-Fa-f]{2})+$"},"sha256":{"title":"SHA-256 digest","description":"8.6: the SHA-256 digest of the file's bytes, 64 lowercase hexadecimal digits. Always present.","type":"string","pattern":"^[0-9a-f]{64}$"},"mediaType":{"title":"Media type","description":"8.6: what kind of file it is, a media type such as \"image/png\" — a type and a subtype as RFC 6838 §4.2 names them, without parameters. Always present.","type":"string","pattern":"^[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]{0,126}/[A-Za-z0-9][A-Za-z0-9!#$&^_.+-]{0,126}$"},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6: extension data on this asset.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7: application-specific data on this asset.","default":{}}},"additionalProperties":false,"oneOf":[{"title":"Packaged asset","description":"8.6.1: located by `path`, and not by `uri`.","required":["path"]},{"title":"External asset","description":"8.6.1: located by `uri`, and not by `path`.","required":["uri"]}]},"building":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 1.4's common members; the reference canonicalizer reads them as its table of constant defaults (9.2 step 1).","title":"Building","description":"1.8: a building of the project — a house, a detached garage, an accessory dwelling. It has only the members every element may carry (1.4) and no others (FS-CORE-1.4.1).","type":"object","properties":{"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6: extension data on this building.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7: application-specific data on this building.","default":{}}},"additionalProperties":false},"defs":{"$comment":"Normative (FLR-ADR-006). The definitions here carry no `default`: a constant default belongs to a member, so it is written where the member is declared, never on a shared definition. The reference canonicalizer reads the `default` keywords of these schemas as its table of constant defaults (9.2 step 1), so a `default` appears exactly on the members whose default is constant in the spec's tables.","title":"Floorspec Core 0.1 — shared definitions","description":"Quantities, identifiers and the members every element may carry, shared by the other schemas of Floorspec Core 0.1. Every value here is a structural check (tier 3, FS-SCH-001); nothing here is an invariant (chapter 10).","$defs":{"length":{"title":"Length","description":"2.1: an integer number of base units of 1/1280 mm, with an absolute value of at most 9,007,199,254,740,991 (2^53 − 1). A length MUST be written as a JSON integer — no fraction and no exponent (FS-CORE-2.1.1). JSON Schema sees the parsed number, so `1.0` and `1e3` would pass `integer` here; a validator applying this schema maps every number written with a fraction or an exponent to a non-number (for example its source text) before validating, so that such a number fails wherever a length is expected.","type":"integer","minimum":-9007199254740991,"maximum":9007199254740991},"positiveLength":{"title":"Positive length","description":"A length (2.1) greater than zero: a level's height (1.8.3), a slab's thickness (6.7.1), an opening's width and height (7.1.2), a layer's thickness (8.3.1), a door or window type's width and height (8.4.1), a texture's size (8.5.2).","type":"integer","minimum":1,"maximum":9007199254740991},"nonNegativeLength":{"title":"Non-negative length","description":"A length (2.1) that is not negative: an opening's offset (7.1.1) and sill (7.1.2), a door or window type's sill (8.4.1).","type":"integer","minimum":0,"maximum":9007199254740991},"angle":{"title":"Angle","description":"2.4: an integer number of microdegrees (10^-6 degree), counter-clockwise positive seen from above. An angle MUST be a JSON integer (FS-CORE-2.4.1); as for a length, a number written with a fraction or an exponent is not one. Where a member is an angle, its own definition states its range.","type":"integer"},"point":{"title":"Point","description":"2.6: a JSON array of exactly two lengths, [x, y], in plan coordinates (2.3).","type":"array","items":{"$ref":"#/$defs/defs/$defs/length"},"minItems":2,"maxItems":2},"polygon":{"title":"Polygon","description":"2.6: a JSON array of at least three points, the vertices in order; the last vertex connects back to the first and is not repeated. That a polygon is simple and encloses a positive area (FS-CORE-2.6.1) is an invariant (FS-INV-009), not checked here.","type":"array","items":{"$ref":"#/$defs/defs/$defs/point"},"minItems":3},"id":{"title":"Element ID","description":"3.1: an element's ID is its member name in its collection, and MUST match ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$ (FS-CORE-3.1.1). That an ID is unique across all collections (FS-CORE-3.1.2) is an invariant (FS-INV-001), not checked here.","type":"string","pattern":"^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$"},"reference":{"title":"Reference","description":"3.2: a member whose value is the ID of another element, so it has the form of an ID (3.1). That it resolves to an element of the right collection and kind (FS-CORE-3.2.1, FS-CORE-3.2.2) is an invariant (FS-INV-002, FS-INV-003), not checked here.","type":"string","pattern":"^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$"},"extensionName":{"title":"Extension name","description":"1.6: a prefix and a name joined by an underscore — FS_ (official), EXT_ (multi-implementer) or a registered vendor prefix of 2 to 8 capitals or digits. Every extension name MUST match ^(FS|EXT|[A-Z0-9]{2,8})_[A-Za-z0-9]+$ (FS-CORE-1.6.1).","type":"string","pattern":"^(FS|EXT|[A-Z0-9]{2,8})_[A-Za-z0-9]+$"},"extensions":{"title":"Extensions","description":"1.6: an object mapping an extension name to that extension's data. The data is defined by the extension's own specification and is any JSON here. That every member name is also a member of extensionsUsed (FS-CORE-1.6.3) is an invariant (FS-INV-005), not checked here.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/extensionName"},"additionalProperties":true},"extras":{"title":"Extras","description":"1.7: an object for application-specific data that no specification defines. Its content is any JSON and is never read by derivation (FS-CORE-1.7.1).","type":"object","additionalProperties":true},"name":{"title":"Name","description":"1.4: a human-readable label of 1 to 200 characters, never read by derivation.","type":"string","minLength":1,"maxLength":200}}},"floorspec":{"$comment":"Normative (FLR-ADR-006): this hand-written schema is the source; TypeScript types are generated from it, never the reverse. The `default` keywords in these schemas are exactly the constant defaults of Floorspec Core 0.1 (1.5) — the reference canonicalizer reads them as its table of constant defaults (9.2 step 1). A member whose default is derived, and every typed property (8.2), carries no `default`; never add one for documentation.","title":"Floorspec Core 0.1 document","description":"1.1: a Floorspec document is a JSON object (FS-CORE-1.1.1) whose members are the version declaration, the project, an optional site, the element collections, the extension declarations and extras, and no other member (FS-CORE-1.1.2). This schema checks structure only — tier 3 of chapter 10, reported as FS-SCH-001. The invariants of chapter 10 (references resolve, IDs are unique, the wall graph is planar, rooms and openings fit, extensions are declared) need a validator. Every length is an integer (2.1): a number written with a fraction or an exponent must be mapped to a non-number before this schema is applied.","type":"object","required":["floorspec","project"],"properties":{"floorspec":{"title":"Version declaration","description":"1.2: the version of Floorspec Core the document targets, as \"<major>.<minor>\". A document that targets this draft MUST declare \"0.1\" (FS-CORE-1.2.1). A string naming another version is rejected before this schema is applied, with FS-DOC-001 (FS-CORE-1.2.2).","const":"0.1"},"project":{"$ref":"#/$defs/project","description":"1.1, 1.8: the project the document describes. Present in every document."},"site":{"$ref":"#/$defs/site","description":"1.1, 1.8: the project's site. Absent: the project has no site."},"buildings":{"title":"Buildings","description":"1.1, 1.8: the collection of buildings (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/building"},"default":{}},"levels":{"title":"Levels","description":"1.1, 1.8: the collection of levels (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/level"},"default":{}},"junctions":{"title":"Junctions","description":"1.1, 5.1: the collection of junctions (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/junction"},"default":{}},"walls":{"title":"Walls","description":"1.1, 5.2: the collection of walls (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/wall"},"default":{}},"separators":{"title":"Separators","description":"1.1, 5.2: the collection of room separators (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/separator"},"default":{}},"openings":{"title":"Openings","description":"1.1, 7.1: the collection of openings (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/opening"},"default":{}},"rooms":{"title":"Rooms","description":"1.1, 6.5: the collection of rooms (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/room"},"default":{}},"slabs":{"title":"Slabs","description":"1.1, 6.7: the collection of slabs (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/slab"},"default":{}},"types":{"title":"Types","description":"1.1, 8.1: the collection of types (1.4), keyed by element ID; each type's kind is given by its `kind` member.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/type"},"default":{}},"materials":{"title":"Materials","description":"1.1, 8.5: the collection of materials (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/material"},"default":{}},"assets":{"title":"Assets","description":"1.1, 8.6: the collection of assets (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/asset"},"default":{}},"extensionsUsed":{"title":"Extensions used","description":"1.6: maps the name of every extension the document uses (FS-CORE-1.6.1) to the version of that extension it targets, written <major>.<minor>, optionally .<patch> and a -prerelease suffix.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/extensionName"},"additionalProperties":{"title":"Extension version","description":"1.6: the version of the extension the document targets.","type":"string","pattern":"^\\d+\\.\\d+(\\.\\d+)?(-[0-9A-Za-z.-]+)?$"},"default":{}},"extensionsRequired":{"title":"Extensions required","description":"1.6: the extensions a reader must implement to read the document correctly, each named once (FS-CORE-1.6.1). That each is also in extensionsUsed (FS-CORE-1.6.2) is an invariant (FS-INV-004), not checked here.","type":"array","items":{"$ref":"#/$defs/defs/$defs/extensionName"},"uniqueItems":true,"default":[]},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.6: document-level extension data, including kinds an extension adds, keyed by extension name.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.7: application-specific data for the document as a whole.","default":{}}},"additionalProperties":false},"junction":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 5.1's Junction table; the reference canonicalizer reads them as its table of constant defaults (9.2 step 1).","title":"Junction","description":"5.1: a node of a level's wall graph — a point on a level where walls and separators start and end. Every junction MUST reference a level (FS-CORE-1.3.2). It has only the members of its table (FS-CORE-1.4.1). That no two junctions on a level share a position (FS-CORE-5.1.1) is an invariant (FS-INV-101), not checked here.","type":"object","required":["level","position"],"properties":{"level":{"$ref":"#/$defs/defs/$defs/reference","description":"1.3, 5.1: a reference to the level the junction is on. Always present."},"position":{"$ref":"#/$defs/defs/$defs/point","description":"5.1: where the junction is, in plan. Always present."},"join":{"$ref":"#/$defs/junction/$defs/join","description":"5.1, 5.8: how the walls meeting here are cut.","default":{"kind":"mitre"}},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6: extension data on this junction.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7: application-specific data on this junction.","default":{}}},"additionalProperties":false,"$defs":{"join":{"title":"Join override","description":"5.8: how the walls meeting at the junction are cut — the default mitre, or a butt join naming one or two walls that run through. Whether a butt join applies to its junction (FS-CORE-5.8.1 to 5.8.3) is an invariant (FS-INV-111), not checked here.","type":"object","required":["kind"],"properties":{"kind":{"title":"Join kind","description":"5.8: \"mitre\" (the default join of 5.7) or \"butt\".","type":"string","enum":["mitre","butt"]}},"oneOf":[{"title":"Mitre join","description":"5.8: { \"kind\": \"mitre\" } — the default join, as 5.7.","type":"object","required":["kind"],"properties":{"kind":{"description":"5.8: \"mitre\".","const":"mitre"}},"additionalProperties":false},{"title":"Butt join","description":"5.8: { \"kind\": \"butt\", \"through\": [W] } or { \"kind\": \"butt\", \"through\": [W1, W2] } — one or two walls run through the junction and every other edge stops against them.","type":"object","required":["kind","through"],"properties":{"kind":{"description":"5.8: \"butt\".","const":"butt"},"through":{"title":"Through walls","description":"5.8: references to the one or two walls that run through the junction.","type":"array","items":{"$ref":"#/$defs/defs/$defs/reference"},"minItems":1,"maxItems":2}},"additionalProperties":false}]}}},"layer":{"$comment":"Normative (FLR-ADR-006). A layer's members have no constant default, so this file carries no `default`; the reference canonicalizer reads the `default` keywords of these schemas as its table of constant defaults (9.2 step 1).","title":"Layer","description":"8.3: one layer of a wall assembly, in a wall type's `layers` or a wall's own. It has only the members of its table.","type":"object","required":["thickness","function"],"properties":{"thickness":{"$ref":"#/$defs/defs/$defs/positiveLength","description":"8.3: the layer's thickness, a length that MUST be greater than zero (FS-CORE-8.3.1). Always present."},"function":{"title":"Layer function","description":"4.3: what the layer does. It MUST be one of the terms of 4.3's table (FS-CORE-4.3.1); the layer functions are closed in this draft. Always present.","type":"string","enum":["core","substrate","insulation","membrane","airGap","finish"]},"material":{"$ref":"#/$defs/defs/$defs/reference","description":"8.3: a reference to the material the layer is made of. Absent by default."}},"additionalProperties":false,"$defs":{"layers":{"title":"Layers","description":"8.3: an assembly from the wall's left (exterior) face to its right (interior) face. A layers array MUST contain at least one layer (FS-CORE-8.3.1).","type":"array","items":{"$ref":"#/$defs/layer"},"minItems":1}}},"level":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 1.8's Level table; the reference canonicalizer reads them as its table of constant defaults (9.2 step 1).","title":"Level","description":"1.8: a level of a building. Every level MUST reference a building (FS-CORE-1.3.1). It has only the members of its table (FS-CORE-1.4.1).","type":"object","required":["building","elevation","height"],"properties":{"building":{"$ref":"#/$defs/defs/$defs/reference","description":"1.3, 1.8: a reference to the building the level is in. Always present."},"elevation":{"$ref":"#/$defs/defs/$defs/length","description":"1.8: the level's datum — the height of its finished floor above project zero, a length (2.1). Always present."},"height":{"$ref":"#/$defs/defs/$defs/positiveLength","description":"1.8: floor-to-floor height, the default top of the level's walls (5.9). Always present, and MUST be greater than zero (FS-CORE-1.8.3)."},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6: extension data on this level.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7: application-specific data on this level.","default":{}}},"additionalProperties":false},"material":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 8.5's table; the reference canonicalizer reads them as its table of constant defaults (9.2 step 1).","title":"Material","description":"8.5: what a layer, a finish or a slab's surface is made of. It has only the members of its table (FS-CORE-1.4.1).","type":"object","properties":{"color":{"title":"Colour","description":"8.5: the material's base colour as \"#rrggbb\", lowercase hexadecimal sRGB; it MUST match ^#[0-9a-f]{6}$ (FS-CORE-8.5.1). Absent by default.","type":"string","pattern":"^#[0-9a-f]{6}$"},"texture":{"title":"Texture","description":"8.5: an image tiled across the surface; one tile covers `size` [w, h] base units. Absent by default; when present, both members are present.","type":"object","required":["asset","size"],"properties":{"asset":{"$ref":"#/$defs/defs/$defs/reference","description":"8.5: a reference to the asset holding the image."},"size":{"title":"Tile size","description":"8.5: [w, h], the size one tile covers. It MUST be two lengths greater than zero (FS-CORE-8.5.2).","type":"array","items":{"$ref":"#/$defs/defs/$defs/positiveLength"},"minItems":2,"maxItems":2}},"additionalProperties":false},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6: extension data on this material.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7: application-specific data on this material.","default":{}}},"additionalProperties":false},"opening":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 7.1's table (hinge, swing, extensions, extras). `width`, `height` and `sill` are typed properties (8.2) that resolve from `fill`, so they deliberately have none — an opening that states \"sill\": 0 keeps it. The reference canonicalizer reads these keywords as its table of constant defaults (9.2 step 1).","title":"Opening","description":"7.1: a hole in a wall — a door, a window or a plain cased opening — hosted on its wall and placed by distances along it. It has only the members of its table (FS-CORE-1.4.1). That its width and height resolve (FS-CORE-7.2.1) and that it fits its wall (7.3) are invariants, not checked here.","type":"object","required":["wall","offset"],"properties":{"wall":{"$ref":"#/$defs/defs/$defs/reference","description":"7.1: a reference to the host wall. Always present."},"offset":{"$ref":"#/$defs/defs/$defs/nonNegativeLength","description":"7.1: the distance from the wall's start junction along its location line to the opening's near edge. Always present, and MUST NOT be negative (FS-CORE-7.1.1)."},"width":{"$ref":"#/$defs/defs/$defs/positiveLength","description":"7.1: the opening's width along the wall, which MUST be greater than zero (FS-CORE-7.1.2). A typed property (8.2): absent, it resolves from `fill` (7.2)."},"height":{"$ref":"#/$defs/defs/$defs/positiveLength","description":"7.1: the opening's height, which MUST be greater than zero (FS-CORE-7.1.2). A typed property (8.2): absent, it resolves from `fill` (7.2)."},"sill":{"$ref":"#/$defs/defs/$defs/nonNegativeLength","description":"7.1: the height of the opening's bottom above the wall's base, which MUST NOT be negative (FS-CORE-7.1.2). A typed property (8.2): absent, it resolves from `fill`, else 0 (7.2)."},"fill":{"$ref":"#/$defs/defs/$defs/reference","description":"7.1: a reference to a type of kind doorType or windowType that fills the opening. Absent: an empty opening."},"hinge":{"title":"Hinge","description":"7.1: for a door, the jamb its leaf hangs from — the one nearer the wall's start or its end.","type":"string","enum":["start","end"],"default":"start"},"swing":{"title":"Swing","description":"7.1: for a door, the side of the wall, seen along the wall's direction, that its leaf opens into.","type":"string","enum":["left","right"],"default":"right"},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6: extension data on this opening.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7: application-specific data on this opening.","default":{}}},"additionalProperties":false},"project":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 1.8's Project table; the reference canonicalizer reads them as its table of constant defaults (9.2 step 1).","title":"Project","description":"1.8: the one project a document describes. It is not an element: it carries no extensions, and only the members of its table.","type":"object","required":["name"],"properties":{"name":{"title":"Project name","description":"1.8: the project's name, 1–200 characters. Always present.","type":"string","minLength":1,"maxLength":200},"description":{"title":"Project description","description":"1.8: free text, up to 2000 characters. Absent by default.","type":"string","maxLength":2000},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.7, 1.8: application-specific data for the project.","default":{}}},"additionalProperties":false},"room":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 6.5's table; the reference canonicalizer reads them as its table of constant defaults (9.2 step 1).","title":"Room","description":"6.5: a room — what cannot be derived about a bounded face of its level's wall graph: its name, its function, its finishes, and the anchor that says which face it is. Every room MUST reference a level (FS-CORE-1.3.2). It has only the members of its table (FS-CORE-1.4.1). Where its anchor lies (6.3) is an invariant, not checked here.","type":"object","required":["level","anchor"],"properties":{"level":{"$ref":"#/$defs/defs/$defs/reference","description":"1.3, 6.5: a reference to the level the room is on. Always present."},"anchor":{"$ref":"#/$defs/defs/$defs/point","description":"6.3, 6.5: a point on the room's level; the face that contains it is the room's face. Always present."},"function":{"$ref":"#/$defs/room/$defs/function","description":"4.1, 6.5: what the room is for.","default":"unspecified"},"wallFinish":{"$ref":"#/$defs/defs/$defs/reference","description":"6.5: a reference to the material that finishes the walls facing this room. Absent by default."},"floorFinish":{"$ref":"#/$defs/defs/$defs/reference","description":"6.5: a reference to the floor finish's material. Absent by default."},"ceilingFinish":{"$ref":"#/$defs/defs/$defs/reference","description":"6.5: a reference to the ceiling finish's material. Absent by default."},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6: extension data on this room.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7: application-specific data on this room.","default":{}}},"additionalProperties":false,"$defs":{"function":{"title":"Room function","description":"4.1: a room's function MUST be either one of the terms of 4.1's table or an extension term (FS-CORE-4.1.1). That an extension term's extension is in extensionsUsed (FS-CORE-4.2.1) is an invariant (FS-INV-006), not checked here.","type":"string","anyOf":[{"title":"Core room function","description":"4.1: one of the fourteen core terms.","type":"string","enum":["unspecified","sleeping","bath","kitchen","living","dining","office","laundry","utility","storage","circulation","mechanical","garage","exterior"]},{"title":"Extension term","description":"4.2: <extension name>:<term>, such as EXT_wellness:sauna, where the extension name matches 1.6's pattern and the term matches ^[a-z][A-Za-z0-9]*$.","type":"string","pattern":"^(FS|EXT|[A-Z0-9]{2,8})_[A-Za-z0-9]+:[a-z][A-Za-z0-9]*$"}]}}},"separator":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 5.2's Separator table; the reference canonicalizer reads them as its table of constant defaults (9.2 step 1).","title":"Separator","description":"5.2: a room separator — a boundary of zero thickness that divides rooms without building anything, an edge of its level's wall graph. Every separator MUST reference a level (FS-CORE-1.3.2). It has only the members of its table (FS-CORE-1.4.1).","type":"object","required":["level","start","end"],"properties":{"level":{"$ref":"#/$defs/defs/$defs/reference","description":"1.3, 5.2: a reference to the level the separator is on. Always present."},"start":{"$ref":"#/$defs/defs/$defs/reference","description":"5.2: a reference to the junction at one end. Always present."},"end":{"$ref":"#/$defs/defs/$defs/reference","description":"5.2: a reference to the junction at the other end. Always present."},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6: extension data on this separator.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7: application-specific data on this separator.","default":{}}},"additionalProperties":false},"site":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 1.8's Site table; the reference canonicalizer reads them as its table of constant defaults (9.2 step 1).","title":"Site","description":"1.8: the project's site. A project with no site yet omits it. It is not an element: it carries no name and no extensions.","type":"object","properties":{"trueNorth":{"title":"True north","description":"1.8: the angle (2.4) from project north (+Y) to true north, counter-clockwise positive, in microdegrees. It MUST be greater than −180,000,000 and at most 180,000,000 (FS-CORE-1.8.1).","type":"integer","exclusiveMinimum":-180000000,"maximum":180000000,"default":0},"location":{"title":"Location","description":"1.8: the site's WGS 84 position in microdegrees. Absent by default; when present, both members are present.","type":"object","required":["latitude","longitude"],"properties":{"latitude":{"title":"Latitude","description":"1.8: an angle (2.4) in [−90,000,000, 90,000,000] microdegrees (FS-CORE-1.8.2).","type":"integer","minimum":-90000000,"maximum":90000000},"longitude":{"title":"Longitude","description":"1.8: an angle (2.4) in (−180,000,000, 180,000,000] microdegrees (FS-CORE-1.8.2).","type":"integer","exclusiveMinimum":-180000000,"maximum":180000000}},"additionalProperties":false},"boundary":{"$ref":"#/$defs/defs/$defs/polygon","description":"1.8: the lot line, a polygon (2.6) in project coordinates. Absent by default."},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.7, 1.8: application-specific data for the site.","default":{}}},"additionalProperties":false},"slab":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 6.7's table; the reference canonicalizer reads them as its table of constant defaults (9.2 step 1).","title":"Slab","description":"6.7: an authored floor or deck that is not derived from a room — a patio, a porch deck, a landing. Every slab MUST reference a level (FS-CORE-1.3.2). It has only the members of its table (FS-CORE-1.4.1).","type":"object","required":["level","boundary","thickness"],"properties":{"level":{"$ref":"#/$defs/defs/$defs/reference","description":"1.3, 6.7: a reference to the level the slab belongs to. Always present."},"boundary":{"$ref":"#/$defs/defs/$defs/polygon","description":"6.7: the slab's outline in plan, a polygon (2.6). Always present. That it is simple with positive area (FS-CORE-2.6.1) is an invariant (FS-INV-009), not checked here."},"thickness":{"$ref":"#/$defs/defs/$defs/positiveLength","description":"6.7: the slab's thickness. Always present, and MUST be greater than zero (FS-CORE-6.7.1)."},"offset":{"$ref":"#/$defs/defs/$defs/length","description":"6.7: the height of the slab's top above its level's elevation.","default":0},"material":{"$ref":"#/$defs/defs/$defs/reference","description":"6.7: a reference to the material of the slab's top surface. Absent by default."},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6: extension data on this slab.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7: application-specific data on this slab.","default":{}}},"additionalProperties":false},"type":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 8.3's and 8.4's tables (extensions, extras). A type's `layers`, `width`, `height` and `sill` have no default. The reference canonicalizer reads these keywords as its table of constant defaults (9.2 step 1).","title":"Type","description":"8.1: a reusable definition that elements refer to instead of repeating — a wall assembly, a door or a window. A type MUST have a `kind` from 8.1's table (FS-CORE-8.1.1), and has only the members of that kind's table (FS-CORE-1.4.1).","type":"object","required":["kind"],"properties":{"kind":{"title":"Kind","description":"8.1: which kind of type this is.","type":"string","enum":["wallType","doorType","windowType"]}},"oneOf":[{"$ref":"#/$defs/type/$defs/wallType"},{"$ref":"#/$defs/type/$defs/doorType"},{"$ref":"#/$defs/type/$defs/windowType"}],"$defs":{"wallType":{"title":"Wall type","description":"8.3: a wall assembly, used by a wall's `type`.","type":"object","required":["kind","layers"],"properties":{"kind":{"description":"8.1, 8.3: \"wallType\".","const":"wallType"},"layers":{"$ref":"#/$defs/layer/$defs/layers","description":"8.3: the assembly, at least one layer (FS-CORE-8.3.1), from the wall's left (exterior) face to its right (interior) face. Always present."},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4, 8.1: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6, 8.1: extension data on this type.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7, 8.1: application-specific data on this type.","default":{}}},"additionalProperties":false},"doorType":{"title":"Door type","description":"8.4: a door, used by an opening's `fill`.","type":"object","required":["kind"],"properties":{"kind":{"description":"8.1, 8.4: \"doorType\".","const":"doorType"},"width":{"$ref":"#/$defs/defs/$defs/positiveLength","description":"8.4: the width of every opening the type fills, unless the opening overrides it; when present, greater than zero (FS-CORE-8.4.1). Absent by default."},"height":{"$ref":"#/$defs/defs/$defs/positiveLength","description":"8.4: likewise, the height; when present, greater than zero (FS-CORE-8.4.1). Absent by default."},"sill":{"$ref":"#/$defs/defs/$defs/nonNegativeLength","description":"8.4: likewise, the sill; when present, not negative (FS-CORE-8.4.1). Absent by default."},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4, 8.1: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6, 8.1: extension data on this type.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7, 8.1: application-specific data on this type.","default":{}}},"additionalProperties":false},"windowType":{"title":"Window type","description":"8.4: a window, used by an opening's `fill`.","type":"object","required":["kind"],"properties":{"kind":{"description":"8.1, 8.4: \"windowType\".","const":"windowType"},"width":{"$ref":"#/$defs/defs/$defs/positiveLength","description":"8.4: the width of every opening the type fills, unless the opening overrides it; when present, greater than zero (FS-CORE-8.4.1). Absent by default."},"height":{"$ref":"#/$defs/defs/$defs/positiveLength","description":"8.4: likewise, the height; when present, greater than zero (FS-CORE-8.4.1). Absent by default."},"sill":{"$ref":"#/$defs/defs/$defs/nonNegativeLength","description":"8.4: likewise, the sill; when present, not negative (FS-CORE-8.4.1). Absent by default."},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4, 8.1: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6, 8.1: extension data on this type.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7, 8.1: application-specific data on this type.","default":{}}},"additionalProperties":false}}},"wall":{"$comment":"Normative (FLR-ADR-006). The `default` keywords here are exactly the constant defaults of 5.2's Wall table and 5.9 (justification, base, base.offset, top.offset, extensions, extras). `layers` (a typed property, 8.2), `top` (derived from the level's height, 5.9) and `base.level` (derived: the wall's own level) deliberately have none. The reference canonicalizer reads these keywords as its table of constant defaults (9.2 step 1).","title":"Wall","description":"5.2: a straight, solid wall with a thickness, an edge of its level's wall graph from its start junction to its end junction. Every wall MUST reference a level (FS-CORE-1.3.2). It has only the members of its table (FS-CORE-1.4.1). The wall's graph rules (5.2 to 5.4, 5.7), and that its top is above its base (FS-CORE-5.9.2), are invariants, not checked here.","type":"object","required":["level","start","end"],"properties":{"level":{"$ref":"#/$defs/defs/$defs/reference","description":"1.3, 5.2: a reference to the level the wall is on. Always present."},"start":{"$ref":"#/$defs/defs/$defs/reference","description":"5.2: a reference to the junction where the wall's location line starts. Always present."},"end":{"$ref":"#/$defs/defs/$defs/reference","description":"5.2: a reference to the junction where the location line ends. Always present."},"type":{"$ref":"#/$defs/defs/$defs/reference","description":"5.2, 8.3: a reference to the wall's type, a type of kind wallType. Absent by default."},"layers":{"$ref":"#/$defs/layer/$defs/layers","description":"5.2, 8.3: the wall's own layers, which replace its type's entirely. A typed property (8.2): absent, it resolves from `type`; it has no constant default."},"justification":{"title":"Justification","description":"5.2, 5.4: where the location line sits in the wall's thickness.","type":"string","enum":["center","exteriorFace","interiorFace","coreFace"],"default":"center"},"base":{"title":"Base","description":"5.2, 5.9: the wall's bottom — `level` (absent: the wall's own level, a derived default) plus `offset`.","type":"object","properties":{"level":{"$ref":"#/$defs/defs/$defs/reference","description":"5.9: a reference to the level whose elevation the base is measured from. Absent: the wall's own level (a derived default)."},"offset":{"$ref":"#/$defs/defs/$defs/length","description":"5.9: added to the base level's elevation.","default":0}},"additionalProperties":false,"default":{}},"top":{"title":"Top","description":"5.2, 5.9: the wall's top — level-constrained, { \"level\", \"offset\"? }, or unconnected, { \"height\" }. `top` MUST have either `level` or `height`, and MUST NOT have both; `offset` MUST NOT appear with `height` (FS-CORE-5.9.1). Absent, the top follows the wall's own level's height: a derived default, so it has no `default` here.","type":"object","oneOf":[{"title":"Level-constrained top","description":"5.9: the top is level `level`'s elevation plus `offset`.","type":"object","required":["level"],"properties":{"level":{"$ref":"#/$defs/defs/$defs/reference","description":"5.9: a reference to the level whose elevation the top is measured from."},"offset":{"$ref":"#/$defs/defs/$defs/length","description":"5.9: added to the top level's elevation.","default":0}},"additionalProperties":false},{"title":"Unconnected top","description":"5.9: the top is the base elevation plus `height`.","type":"object","required":["height"],"properties":{"height":{"$ref":"#/$defs/defs/$defs/length","description":"5.9: the wall's height above its base elevation, a length (2.1). That the top ends above the base (FS-CORE-5.9.2) is an invariant (FS-INV-112), not checked here."}},"additionalProperties":false}]},"name":{"$ref":"#/$defs/defs/$defs/name","description":"1.4: a human-readable label, 1–200 characters. Absent by default."},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.4, 1.6: extension data on this wall.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.4, 1.7: application-specific data on this wall.","default":{}}},"additionalProperties":false}}};
const schema32 = {"$comment":"Normative (FLR-ADR-006): this hand-written schema is the source; TypeScript types are generated from it, never the reverse. The `default` keywords in these schemas are exactly the constant defaults of Floorspec Core 0.1 (1.5) — the reference canonicalizer reads them as its table of constant defaults (9.2 step 1). A member whose default is derived, and every typed property (8.2), carries no `default`; never add one for documentation.","title":"Floorspec Core 0.1 document","description":"1.1: a Floorspec document is a JSON object (FS-CORE-1.1.1) whose members are the version declaration, the project, an optional site, the element collections, the extension declarations and extras, and no other member (FS-CORE-1.1.2). This schema checks structure only — tier 3 of chapter 10, reported as FS-SCH-001. The invariants of chapter 10 (references resolve, IDs are unique, the wall graph is planar, rooms and openings fit, extensions are declared) need a validator. Every length is an integer (2.1): a number written with a fraction or an exponent must be mapped to a non-number before this schema is applied.","type":"object","required":["floorspec","project"],"properties":{"floorspec":{"title":"Version declaration","description":"1.2: the version of Floorspec Core the document targets, as \"<major>.<minor>\". A document that targets this draft MUST declare \"0.1\" (FS-CORE-1.2.1). A string naming another version is rejected before this schema is applied, with FS-DOC-001 (FS-CORE-1.2.2).","const":"0.1"},"project":{"$ref":"#/$defs/project","description":"1.1, 1.8: the project the document describes. Present in every document."},"site":{"$ref":"#/$defs/site","description":"1.1, 1.8: the project's site. Absent: the project has no site."},"buildings":{"title":"Buildings","description":"1.1, 1.8: the collection of buildings (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/building"},"default":{}},"levels":{"title":"Levels","description":"1.1, 1.8: the collection of levels (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/level"},"default":{}},"junctions":{"title":"Junctions","description":"1.1, 5.1: the collection of junctions (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/junction"},"default":{}},"walls":{"title":"Walls","description":"1.1, 5.2: the collection of walls (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/wall"},"default":{}},"separators":{"title":"Separators","description":"1.1, 5.2: the collection of room separators (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/separator"},"default":{}},"openings":{"title":"Openings","description":"1.1, 7.1: the collection of openings (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/opening"},"default":{}},"rooms":{"title":"Rooms","description":"1.1, 6.5: the collection of rooms (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/room"},"default":{}},"slabs":{"title":"Slabs","description":"1.1, 6.7: the collection of slabs (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/slab"},"default":{}},"types":{"title":"Types","description":"1.1, 8.1: the collection of types (1.4), keyed by element ID; each type's kind is given by its `kind` member.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/type"},"default":{}},"materials":{"title":"Materials","description":"1.1, 8.5: the collection of materials (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/material"},"default":{}},"assets":{"title":"Assets","description":"1.1, 8.6: the collection of assets (1.4), keyed by element ID.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/id"},"additionalProperties":{"$ref":"#/$defs/asset"},"default":{}},"extensionsUsed":{"title":"Extensions used","description":"1.6: maps the name of every extension the document uses (FS-CORE-1.6.1) to the version of that extension it targets, written <major>.<minor>, optionally .<patch> and a -prerelease suffix.","type":"object","propertyNames":{"$ref":"#/$defs/defs/$defs/extensionName"},"additionalProperties":{"title":"Extension version","description":"1.6: the version of the extension the document targets.","type":"string","pattern":"^\\d+\\.\\d+(\\.\\d+)?(-[0-9A-Za-z.-]+)?$"},"default":{}},"extensionsRequired":{"title":"Extensions required","description":"1.6: the extensions a reader must implement to read the document correctly, each named once (FS-CORE-1.6.1). That each is also in extensionsUsed (FS-CORE-1.6.2) is an invariant (FS-INV-004), not checked here.","type":"array","items":{"$ref":"#/$defs/defs/$defs/extensionName"},"uniqueItems":true,"default":[]},"extensions":{"$ref":"#/$defs/defs/$defs/extensions","description":"1.6: document-level extension data, including kinds an extension adds, keyed by extension name.","default":{}},"extras":{"$ref":"#/$defs/defs/$defs/extras","description":"1.7: application-specific data for the document as a whole.","default":{}}},"additionalProperties":false};
const schema40 = {"title":"Element ID","description":"3.1: an element's ID is its member name in its collection, and MUST match ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$ (FS-CORE-3.1.1). That an ID is unique across all collections (FS-CORE-3.1.2) is an invariant (FS-INV-001), not checked here.","type":"string","pattern":"^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$"};
const schema44 = {"title":"Extension name","description":"1.6: a prefix and a name joined by an underscore — FS_ (official), EXT_ (multi-implementer) or a registered vendor prefix of 2 to 8 capitals or digits. Every extension name MUST match ^(FS|EXT|[A-Z0-9]{2,8})_[A-Za-z0-9]+$ (FS-CORE-1.6.1).","type":"string","pattern":"^(FS|EXT|[A-Z0-9]{2,8})_[A-Za-z0-9]+$"};
